-- EVENT-BUILT (hackathon 2026-10-23). L2P control plane: contract, registry, fixed recipes.
-- Creates new L2P* schemas only. Does not modify RAW, ANALYTICS, the starter agent or catalog.
USE WAREHOUSE DEFAULT_WH;
USE DATABASE HACKATHON_D2K_PREWORK;

CREATE SCHEMA IF NOT EXISTS L2P          COMMENT='EVENT-BUILT L2P registry, contract and builder procedures.';
CREATE SCHEMA IF NOT EXISTS L2P_STAGE    COMMENT='EVENT-BUILT L2P source snapshots and unreleased candidates. Not for consumers.';
CREATE SCHEMA IF NOT EXISTS L2P_RELEASE  COMMENT='EVENT-BUILT L2P released product versions. Written only by L2P.RELEASE_CANDIDATE.';
CREATE SCHEMA IF NOT EXISTS L2P_CONSUMER COMMENT='EVENT-BUILT L2P bounded consumer read procedures.';

CREATE SEQUENCE IF NOT EXISTS L2P.SEQ_CANDIDATE;
CREATE SEQUENCE IF NOT EXISTS L2P.SEQ_SNAPSHOT;
CREATE SEQUENCE IF NOT EXISTS L2P.SEQ_RUN;
CREATE SEQUENCE IF NOT EXISTS L2P.SEQ_RELEASE;
CREATE SEQUENCE IF NOT EXISTS L2P.SEQ_EVENT;

-- Contract (machine-readable copy also in event/l2p/contract/daily_invoiced_sales.contract.json)
CREATE TABLE IF NOT EXISTS L2P.CONTRACT_FIELDS (
  PRODUCT VARCHAR, CONTRACT_VERSION NUMBER, ORDINAL NUMBER, FIELD_NAME VARCHAR,
  DATA_TYPE VARCHAR, NUMERIC_PRECISION NUMBER, NUMERIC_SCALE NUMBER, IS_KEY BOOLEAN, NULLABLE BOOLEAN, SOURCE_EXPRESSION VARCHAR);
DELETE FROM L2P.CONTRACT_FIELDS WHERE PRODUCT='DAILY_INVOICED_SALES' AND CONTRACT_VERSION=1;
INSERT INTO L2P.CONTRACT_FIELDS VALUES
