 ('DAILY_INVOICED_SALES',1,2,'CUSTOMER_ID','NUMBER',38,0,TRUE,FALSE,'INVOICES.CUSTOMERID'),
 ('DAILY_INVOICED_SALES',1,3,'STOCK_ITEM_ID','NUMBER',38,0,TRUE,FALSE,'INVOICELINES.STOCKITEMID'),
 ('DAILY_INVOICED_SALES',1,4,'CUSTOMER_NAME','TEXT',NULL,NULL,FALSE,TRUE,'CUSTOMERS.CUSTOMERNAME via INVOICES.CUSTOMERID'),
 ('DAILY_INVOICED_SALES',1,5,'STOCK_ITEM_NAME','TEXT',NULL,NULL,FALSE,TRUE,'STOCKITEMS.STOCKITEMNAME via INVOICELINES.STOCKITEMID'),
 ('DAILY_INVOICED_SALES',1,6,'INVOICE_LINE_COUNT','NUMBER',18,0,FALSE,FALSE,'COUNT(INVOICELINES)'),
