 ('DAILY_INVOICED_SALES',1,10,'TOTAL_INCLUDING_TAX','NUMBER',18,2,FALSE,FALSE,'SUM(INVOICELINES.EXTENDEDPRICE)');

-- Fixed recipes. Agents pass only RECIPE_ID; templates are not agent-supplied.
-- Placeholders {{T}} are replaced by the procedure with fully-qualified snapshot clone names.
CREATE TABLE IF NOT EXISTS L2P.RECIPES (
  RECIPE_ID VARCHAR, PRODUCT VARCHAR, CONTRACT_VERSION NUMBER, INTENDED_VALID BOOLEAN,
  DESCRIPTION VARCHAR, SQL_TEMPLATE VARCHAR, SOURCE_DOC_IDS ARRAY);
DELETE FROM L2P.RECIPES;
INSERT INTO L2P.RECIPES
SELECT column1, 'DAILY_INVOICED_SALES', 1, column2, column3, column4, SPLIT(column5, ',') FROM VALUES
 ('DAILY_INVOICED_SALES_V1', TRUE,
  'Correct recipe: invoice-line grain aggregated to invoice date / customer / stock item; header supplies date and customer; amounts exclude tax.',
  'SELECT h.INVOICEDATE::DATE AS INVOICE_DATE, h.CUSTOMERID::NUMBER(38,0) AS CUSTOMER_ID, l.STOCKITEMID::NUMBER(38,0) AS STOCK_ITEM_ID, c.CUSTOMERNAME::VARCHAR AS CUSTOMER_NAME, s.STOCKITEMNAME::VARCHAR AS STOCK_ITEM_NAME, COUNT(*)::NUMBER(18,0) AS INVOICE_LINE_COUNT, SUM(l.QUANTITY)::NUMBER(18,0) AS QUANTITY, SUM(l.EXTENDEDPRICE - l.TAXAMOUNT)::NUMBER(18,2) AS SALES_EXCLUDING_TAX, SUM(l.TAXAMOUNT)::NUMBER(18,2) AS TAX_AMOUNT, SUM(l.EXTENDEDPRICE)::NUMBER(18,2) AS TOTAL_INCLUDING_TAX FROM {{INVOICELINES}} l JOIN {{INVOICES}} h ON h.INVOICEID = l.INVOICEID LEFT JOIN {{CUSTOMERS}} c ON c.CUSTOMERID = h.CUSTOMERID LEFT JOIN {{STOCKITEMS}} s ON s.STOCKITEMID = l.STOCKITEMID GROUP BY 1,2,3,4,5',
  'CONNECTED_6f53633c096a6b56,CONNECTED_1055b17d75582621,CONNECTED_a5086dc0ef985e23,CONNECTED_d6d252dc2b0538ee,DAILY_INVOICE_SALES'),
 ('STOCKGROUP_FANOUT_DEMO', FALSE,
  'Deliberately invalid: joins stock item to stock groups (many-to-many), multiplying invoice lines for multi-group items.',
  'SELECT h.INVOICEDATE::DATE AS INVOICE_DATE, h.CUSTOMERID::NUMBER(38,0) AS CUSTOMER_ID, l.STOCKITEMID::NUMBER(38,0) AS STOCK_ITEM_ID, c.CUSTOMERNAME::VARCHAR AS CUSTOMER_NAME, s.STOCKITEMNAME::VARCHAR AS STOCK_ITEM_NAME, COUNT(*)::NUMBER(18,0) AS INVOICE_LINE_COUNT, SUM(l.QUANTITY)::NUMBER(18,0) AS QUANTITY, SUM(l.EXTENDEDPRICE - l.TAXAMOUNT)::NUMBER(18,2) AS SALES_EXCLUDING_TAX, SUM(l.TAXAMOUNT)::NUMBER(18,2) AS TAX_AMOUNT, SUM(l.EXTENDEDPRICE)::NUMBER(18,2) AS TOTAL_INCLUDING_TAX FROM {{INVOICELINES}} l JOIN {{INVOICES}} h ON h.INVOICEID = l.INVOICEID JOIN {{STOCKITEMSTOCKGROUPS}} g ON g.STOCKITEMID = l.STOCKITEMID LEFT JOIN {{CUSTOMERS}} c ON c.CUSTOMERID = h.CUSTOMERID LEFT JOIN {{STOCKITEMS}} s ON s.STOCKITEMID = l.STOCKITEMID GROUP BY 1,2,3,4,5',
  'CONNECTED_6f53633c096a6b56,CONNECTED_d6d252dc2b0538ee'),
 ('SINGLE_GROUP_OMISSION_DEMO', FALSE,
  'Deliberately invalid: restricts to one stock group, silently dropping invoice lines for items outside that group.',
  'SELECT h.INVOICEDATE::DATE AS INVOICE_DATE, h.CUSTOMERID::NUMBER(38,0) AS CUSTOMER_ID, l.STOCKITEMID::NUMBER(38,0) AS STOCK_ITEM_ID, c.CUSTOMERNAME::VARCHAR AS CUSTOMER_NAME, s.STOCKITEMNAME::VARCHAR AS STOCK_ITEM_NAME, COUNT(*)::NUMBER(18,0) AS INVOICE_LINE_COUNT, SUM(l.QUANTITY)::NUMBER(18,0) AS QUANTITY, SUM(l.EXTENDEDPRICE - l.TAXAMOUNT)::NUMBER(18,2) AS SALES_EXCLUDING_TAX, SUM(l.TAXAMOUNT)::NUMBER(18,2) AS TAX_AMOUNT, SUM(l.EXTENDEDPRICE)::NUMBER(18,2) AS TOTAL_INCLUDING_TAX FROM {{INVOICELINES}} l JOIN {{INVOICES}} h ON h.INVOICEID = l.INVOICEID JOIN {{STOCKITEMSTOCKGROUPS}} g ON g.STOCKITEMID = l.STOCKITEMID AND g.STOCKGROUPID = (SELECT MIN(STOCKGROUPID) FROM {{STOCKITEMSTOCKGROUPS}}) LEFT JOIN {{CUSTOMERS}} c ON c.CUSTOMERID = h.CUSTOMERID LEFT JOIN {{STOCKITEMS}} s ON s.STOCKITEMID = l.STOCKITEMID GROUP BY 1,2,3,4,5',
  'CONNECTED_6f53633c096a6b56,CONNECTED_d6d252dc2b0538ee'),
 ('ORDER_DATE_BASIS_DEMO', FALSE,
  'Deliberately invalid: substitutes order date for invoice date. Totals can match while grouped rows do not.',
  'SELECT o.ORDERDATE::DATE AS INVOICE_DATE, h.CUSTOMERID::NUMBER(38,0) AS CUSTOMER_ID, l.STOCKITEMID::NUMBER(38,0) AS STOCK_ITEM_ID, c.CUSTOMERNAME::VARCHAR AS CUSTOMER_NAME, s.STOCKITEMNAME::VARCHAR AS STOCK_ITEM_NAME, COUNT(*)::NUMBER(18,0) AS INVOICE_LINE_COUNT, SUM(l.QUANTITY)::NUMBER(18,0) AS QUANTITY, SUM(l.EXTENDEDPRICE - l.TAXAMOUNT)::NUMBER(18,2) AS SALES_EXCLUDING_TAX, SUM(l.TAXAMOUNT)::NUMBER(18,2) AS TAX_AMOUNT, SUM(l.EXTENDEDPRICE)::NUMBER(18,2) AS TOTAL_INCLUDING_TAX FROM {{INVOICELINES}} l JOIN {{INVOICES}} h ON h.INVOICEID = l.INVOICEID JOIN {{ORDERS}} o ON o.ORDERID = h.ORDERID LEFT JOIN {{CUSTOMERS}} c ON c.CUSTOMERID = h.CUSTOMERID LEFT JOIN {{STOCKITEMS}} s ON s.STOCKITEMID = l.STOCKITEMID GROUP BY 1,2,3,4,5',
  'CONNECTED_d8398680328033bb,CONNECTED_d6d252dc2b0538ee');

-- Field mappings with the exact evidence text expected in the catalog document.
CREATE TABLE IF NOT EXISTS L2P.RECIPE_MAPPINGS (
  RECIPE_ID VARCHAR, TARGET_FIELD VARCHAR, SOURCE_EXPRESSION VARCHAR, EVIDENCE_DOC_ID VARCHAR, EVIDENCE_TEXT VARCHAR, NOTE VARCHAR);
DELETE FROM L2P.RECIPE_MAPPINGS;
