 ('DAILY_INVOICED_SALES_V1','(calendar zero-fill)',NULL,'DAILY_INVOICE_SALES','Days without invoices are omitted','No zero-fill.'),
 ('DAILY_INVOICED_SALES_V1','(stock group allocation)',NULL,'CONNECTED_d6d252dc2b0538ee','no designated primary group','Group attribution not supported.'),
