CREATE TABLE IF NOT EXISTS L2P.SNAPSHOTS (
  SNAPSHOT_ID VARCHAR, CREATED_AT TIMESTAMP_LTZ, OBJECTS VARIANT, FINGERPRINT VARCHAR, CREATE_QUERY_IDS ARRAY);
CREATE TABLE IF NOT EXISTS L2P.CANDIDATES (
  CANDIDATE_ID VARCHAR, RECIPE_ID VARCHAR, PRODUCT VARCHAR, CONTRACT_VERSION NUMBER, STATE VARCHAR,
  SNAPSHOT_ID VARCHAR, SOURCE_DEFINITIONS VARIANT, MAPPINGS VARIANT, RENDERED_SQL VARCHAR, BUILD_QUERY_ID VARCHAR,
  CANDIDATE_OBJECT VARCHAR, CONTENT_HASH VARCHAR, ROW_COUNT NUMBER,
  PROPOSED_AT TIMESTAMP_LTZ, CREATED_AT TIMESTAMP_LTZ, VALIDATED_AT TIMESTAMP_LTZ, FAILED_AT TIMESTAMP_LTZ, RELEASED_AT TIMESTAMP_LTZ,
  LATEST_VALIDATION_RUN_ID VARCHAR, RELEASED_VERSION NUMBER, FAILURE_REASON VARCHAR, REQUESTED_BY VARCHAR);
CREATE TABLE IF NOT EXISTS L2P.VALIDATION_RUNS (
  RUN_ID VARCHAR, CANDIDATE_ID VARCHAR, SNAPSHOT_ID VARCHAR, STARTED_AT TIMESTAMP_LTZ, FINISHED_AT TIMESTAMP_LTZ,
  CONTENT_HASH_START VARCHAR, CONTENT_HASH_END VARCHAR, OVERALL_STATUS VARCHAR, CHECKS_PASSED NUMBER, CHECKS_FAILED NUMBER);
CREATE TABLE IF NOT EXISTS L2P.CHECK_RESULTS (
  RUN_ID VARCHAR, CANDIDATE_ID VARCHAR, CHECK_NAME VARCHAR, STATUS VARCHAR, OBSERVED VARIANT, EXPECTED VARIANT,
  QUERY_ID VARCHAR, CHECKED_AT TIMESTAMP_LTZ);
CREATE TABLE IF NOT EXISTS L2P.RELEASES (
  VERSION NUMBER, PRODUCT VARCHAR, CANDIDATE_ID VARCHAR, RELEASE_OBJECT VARCHAR, CONTENT_HASH VARCHAR, ROW_COUNT NUMBER,
  SNAPSHOT_ID VARCHAR, VALIDATION_RUN_ID VARCHAR, RELEASED_AT TIMESTAMP_LTZ, IS_CURRENT BOOLEAN, SUPERSEDED_AT TIMESTAMP_LTZ,
  CLONE_QUERY_ID VARCHAR);
CREATE TABLE IF NOT EXISTS L2P.EVENT_LOG (
  EVENT_ID NUMBER, TS TIMESTAMP_LTZ, CANDIDATE_ID VARCHAR, ACTION VARCHAR, OUTCOME VARCHAR, DETAIL VARIANT);
